function churnRate(start, churned){ start=+start; churned=+churned; if(start<=0) return NaN; return churned/start; }
function retentionRate(start, churned){ var c=churnRate(start,churned); return isNaN(c)?NaN:1-c; }
function annualize(monthlyChurn){ monthlyChurn=+monthlyChurn; if(monthlyChurn<=0||monthlyChurn>=1) return NaN; return 1-Math.pow(1-monthlyChurn,12); }
var EXPORTS={churnRate:churnRate, retentionRate:retentionRate, annualize:annualize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ChurnForgePure = EXPORTS; }
